example.snippet:
package main

import (
	"context"
	"fmt"
	"math"
	"math/rand/v2"
)

type MyModule struct{}

// Build and publish image with OCI annotations
func (m *MyModule) Build(ctx context.Context) (string, error) {
	address, err := dag.Container().
		From("alpine:latest").
		WithExec([]string{"apk", "add", "git"}).
		WithWorkdir("/src").
		WithExec([]string{"git", "clone", "https://github.com/dagger/dagger", "."}).
		WithAnnotation("org.opencontainers.image.authors", "John Doe").
		WithAnnotation("org.opencontainers.image.title", "Dagger source image viewer").
		Publish(ctx, fmt.Sprintf("ttl.sh/custom-image-%.0f", math.Floor(rand.Float64()*10000000))) //#nosec
	if err != nil {
		return "", err
	}
	return address, nil
}

import random
from dagger import dag, function, object_type
@object_type class MyModule: @function async def build(self) -> str: """Build and publish image with OCI annotations""" address = await ( dag.container() .from_("alpine:latest") .with_exec(["apk", "add", "git"]) .with_workdir("/src") .with_exec(["git", "clone", "https://github.com/dagger/dagger", "."]) .with_annotation("org.opencontainers.image.authors", "John Doe") .with_annotation( "org.opencontainers.image.title", "Dagger source image viewer" ) .publish(f"ttl.sh/custom-image-{random.randrange(10 * 7)}") ) return address

import { dag, object, func } from "@dagger.io/dagger"

@object()
class MyModule {
  /**
   * Build and publish image with OCI annotations
   */
  @func()
  async build(): Promise {
    const address = await dag
      .container()
      .from("alpine:latest")
      .withExec(["apk", "add", "git"])
      .withWorkdir("/src")
      .withExec(["git", "clone", "https://github.com/dagger/dagger", "."])
      .withAnnotation("org.opencontainers.image.authors", "John Doe")
      .withAnnotation(
        "org.opencontainers.image.title",
        "Dagger source image viewer",
      )
      .publish(`ttl.sh/custom-image-${Math.floor(Math.random() * 10000000)}`)

    return address
  }
}
